class TransferLearningModel(nn.Module):

    def __init__(self, backbone: str='resnet50', train_bn: bool=False, milestones: tuple=(2, 4), batch_size: int=32, lr: float=0.001, lr_scheduler_gamma: float=0.1, num_workers: int=6, **kwargs) -> None:
        """TransferLearningModel.

        Args:
            backbone: Name (as in ``torchvision.models``) of the feature extractor
            train_bn: Whether the BatchNorm layers should be trainable
            milestones: List of two epochs milestones
            lr: Initial learning rate
            lr_scheduler_gamma: Factor by which the learning rate is reduced at each milestone

        """
        super().__init__()
        self.backbone = backbone
        self.train_bn = train_bn
        self.milestones = milestones
        self.batch_size = batch_size
        self.lr = lr
        self.lr_scheduler_gamma = lr_scheduler_gamma
        self.num_workers = num_workers
        self.__build_model()
        self.train_acc = Accuracy(task='binary')
        self.valid_acc = Accuracy(task='binary')
        self.hparams = SimpleNamespace(backbone=backbone, train_bn=train_bn, milestones=milestones, batch_size=batch_size, lr=lr, lr_scheduler_gamma=lr_scheduler_gamma, num_workers=num_workers)

    def __build_model(self):
        """Define model layers & loss."""
        backbone = get_torchvision_model(self.backbone, weights='DEFAULT')
        _layers = list(backbone.children())[:-1]
        self.feature_extractor = nn.Sequential(*_layers)
        _fc_layers = [nn.Linear(2048, 256), nn.ReLU(), nn.Linear(256, 32), nn.Linear(32, 1)]
        self.fc = nn.Sequential(*_fc_layers)
        self.loss_func = F.binary_cross_entropy_with_logits

    def forward(self, x):
        """Forward pass.

        Returns logits.

        """
        x = self.feature_extractor(x)
        x = x.squeeze(-1).squeeze(-1)
        return self.fc(x)

    def loss(self, logits, labels):
        return self.loss_func(input=logits, target=labels)


